const defaults={light:{bg:'#f5f0e9',paper:'#fffaf3',ink:'#213852',accent:'#967338',side:'#eee5d9'},dark:{bg:'#192a42',paper:'#243b56',ink:'#f5efdf',accent:'#dfc58e',side:'#23344c'}};
const keys=['bg','paper','ink','accent','side'];
export function applyCustomTheme(w){
 if(w.palette!=='custom'){for(const key of [...keys,'soft','line','muted','side-ink','card-paper','card-ink','card-muted','gold','custom-logo-filter','custom-active-ink'])document.body.style.removeProperty('--'+key);return;}
 const mode=w.theme==='dark'?'dark':'light',colors={...defaults[mode],...w.customTheme?.[mode]};
 for(const key of keys)document.body.style.setProperty('--'+key,/^#[0-9a-f]{6}$/i.test(colors[key])?colors[key]:defaults[mode][key]);
 const isLight=hex=>{const c=hex.match(/[0-9a-f]{2}/gi)?.map(v=>parseInt(v,16))||[0,0,0];return c[0]*.299+c[1]*.587+c[2]*.114>150;};
 document.body.style.setProperty('--side-ink',isLight(colors.side)?'#192a42':'#f5efdf');document.body.style.setProperty('--custom-logo-filter',isLight(colors.side)?'brightness(0)':'brightness(0) invert(1)');document.body.style.setProperty('--custom-active-ink',isLight(colors.accent)?'#192a42':'#fffaf3');
 for(const [key,value] of Object.entries({'card-paper':'var(--paper)','card-ink':'var(--ink)','card-muted':'var(--muted)',gold:'var(--accent)'}))document.body.style.setProperty('--'+key,value);
 document.body.style.setProperty('--soft','color-mix(in srgb,var(--ink) 7%,var(--paper))');document.body.style.setProperty('--line','color-mix(in srgb,var(--ink) 22%,var(--paper))');document.body.style.setProperty('--muted','color-mix(in srgb,var(--ink) 70%,var(--paper))');
}
export function mountCustomTheme(menu,getWorld,save,apply,sync){
 const section=document.createElement('section');section.className='custom-theme-editor';section.innerHTML=`<button type="button" class="custom-theme-choice" data-palette-choice="custom"><span>✧</span><span><strong>Meu tema</strong><small>Crie as cores deste universo</small></span></button><div class="custom-theme-colors" hidden><p>Edite as cores do modo <strong id="customModeLabel"></strong>.</p>${[['bg','Fundo'],['paper','Cartões e painéis'],['ink','Texto'],['accent','Destaque'],['side','Barra lateral']].map(([key,label])=>`<label><span>${label}</span><input type="color" data-custom-color="${key}" aria-label="${label}"><input type="text" data-custom-hex="${key}" aria-label="Código da cor ${label}" maxlength="7" pattern="#[0-9a-fA-F]{6}"></label>`).join('')}<button type="button" class="text-link" id="resetCustomTheme">Restaurar estas cores</button></div>`;menu.querySelector('.font-picker').before(section);
 const update=()=>{const w=getWorld(),mode=w.theme==='dark'?'dark':'light',colors={...defaults[mode],...w.customTheme?.[mode]};section.querySelector('.custom-theme-colors').hidden=w.palette!=='custom';section.querySelector('#customModeLabel').textContent=mode==='dark'?'escuro':'claro';section.querySelector('.custom-theme-choice').setAttribute('aria-pressed',String(w.palette==='custom'));keys.forEach(key=>{section.querySelector(`[data-custom-color=${key}]`).value=colors[key];const hex=section.querySelector(`[data-custom-hex=${key}]`);if(document.activeElement!==hex)hex.value=colors[key];});applyCustomTheme(w);};
 section.querySelector('.custom-theme-choice').onclick=()=>{getWorld().palette='custom';apply();sync();save();update();};
 const change=(key,value)=>{if(!/^#[0-9a-f]{6}$/i.test(value))return;const w=getWorld(),mode=w.theme==='dark'?'dark':'light';w.customTheme??={};w.customTheme[mode]={...defaults[mode],...w.customTheme[mode],[key]:value};w.palette='custom';applyCustomTheme(w);save();update();};
 section.querySelectorAll('[data-custom-color]').forEach(input=>input.oninput=()=>change(input.dataset.customColor,input.value));section.querySelectorAll('[data-custom-hex]').forEach(input=>input.oninput=()=>change(input.dataset.customHex,input.value));section.querySelector('#resetCustomTheme').onclick=()=>{const w=getWorld();w.customTheme??={};w.customTheme[w.theme==='dark'?'dark':'light']={...defaults[w.theme==='dark'?'dark':'light']};update();save();};update();return update;
}
